# Optional presentation state. It never authorizes or changes scientific inputs.
team_canvas_limits <- list(nodes = 40L, bytes = 24 * 1024^2, snapshot = 4 * 1024^2)
# This is a server-side allowlist matching www/team/js/illustrations.js. The
# SVG is always regenerated by the client from this ID; checkpoint markup is
# never treated as the source of truth.
team_canvas_illustration_ids <- c(
  "cohort-donor", "whole-blood", "serum-vial", "pipette", "microplate",
  "extraction-tubes", "centrifuge", "cold-storage", "lc-ms", "lipid-bilayer",
  "neutrophil", "macrophage", "workflow-arrow", "workflow-overview", "lipid-class-taxonomy", "study-workflow-scd",
  "donor-person", "cohort-label", "connector-arrow", "lipid-class-chip", "sample-vial-component"
)

team_canvas_fail <- function(message = "Invalid figure canvas state.") stop(message, call. = FALSE)
team_canvas_object <- function(value, allowed, required = character()) {
  if (!is.list(value) || (length(value) && (is.null(names(value)) ||
      anyNA(names(value)) || anyDuplicated(names(value)))) ||
      !all(names(value) %in% allowed) || !all(required %in% names(value))) team_canvas_fail()
  if (!length(value)) names(value) <- character()
  value
}
team_canvas_string <- function(value, max_chars, empty = TRUE) {
  if (!is.character(value) || length(value) != 1L || is.na(value) ||
      nchar(value, type = "bytes") > 4 * max_chars || nchar(value) > max_chars ||
      (!empty && !nzchar(value)) || is.na(iconv(value, to = "UTF-8")) ||
      grepl("[\\x01-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]", value, perl = TRUE)) team_canvas_fail()
  value
}
team_canvas_number <- function(value, low, high) {
  if (!is.numeric(value) || length(value) != 1L || !is.finite(value) || value < low || value > high) team_canvas_fail()
  as.numeric(value)
}
team_canvas_boolean <- function(value) {
  if (!is.logical(value) || length(value) != 1L || is.na(value)) team_canvas_fail()
  value
}
team_canvas_base64 <- function(value) {
  if (!nzchar(value) || nchar(value, type = "bytes") %% 4L != 0L ||
      !grepl("^[A-Za-z0-9+/]*={0,2}$", value)) team_canvas_fail("Invalid saved figure encoding.")
  bytes <- tryCatch(jsonlite::base64_dec(value), error = function(e) NULL)
  if (is.null(bytes) || !identical(gsub("[\r\n]", "", jsonlite::base64_enc(bytes)), value)) team_canvas_fail("Invalid saved figure encoding.")
  bytes
}
team_canvas_png <- function(bytes) {
  signature <- as.raw(c(137, 80, 78, 71, 13, 10, 26, 10))
  if (length(bytes) < 33L || length(bytes) > team_canvas_limits$snapshot ||
      !identical(bytes[seq_len(8L)], signature) ||
      !identical(rawToChar(bytes[13:16]), "IHDR")) team_canvas_fail("Invalid saved PNG figure.")
  invisible(TRUE)
}

team_canvas_svg <- function(svg) {
  if (!is.character(svg) || length(svg) != 1L || is.na(svg) ||
      nchar(svg, type = "bytes") > team_canvas_limits$snapshot ||
      grepl("<!\\s*(DOCTYPE|ENTITY)", svg, ignore.case = TRUE, perl = TRUE))
    team_canvas_fail("Unsafe saved SVG figure.")
  if (!requireNamespace("xml2", quietly = TRUE)) team_canvas_fail("SVG figure validation is unavailable.")
  doc <- tryCatch(xml2::read_xml(charToRaw(enc2utf8(svg)), options = "NONET"), error = function(e) NULL)
  if (is.null(doc) || xml2::xml_name(doc) != "svg" ||
      length(xml2::xml_find_all(doc, "//processing-instruction()"))) team_canvas_fail("Unsafe saved SVG figure.")
  elements <- xml2::xml_find_all(doc, "//*")
  allowed_elements <- c("svg", "g", "defs", "clipPath", "mask", "path", "rect", "circle", "ellipse", "line",
    "polyline", "polygon", "text", "tspan", "title", "desc", "linearGradient", "radialGradient", "stop",
    "pattern", "image", "use", "marker", "symbol")
  allowed_attributes <- c("id", "class", "style", "transform", "x", "y", "x1", "y1", "x2", "y2", "cx", "cy",
    "r", "rx", "ry", "d", "points", "width", "height", "viewBox", "preserveAspectRatio", "version", "fill",
    "fill-opacity", "fill-rule", "clip-rule", "stroke", "stroke-width", "stroke-opacity", "stroke-dasharray",
    "stroke-dashoffset", "stroke-linecap", "stroke-linejoin", "stroke-miterlimit", "opacity", "font-family",
    "font-size", "font-style", "font-weight", "text-anchor", "dominant-baseline", "alignment-baseline",
    "letter-spacing", "word-spacing", "dx", "dy", "rotate", "textLength", "lengthAdjust", "clip-path", "clipPathUnits",
    "mask", "maskUnits", "maskContentUnits", "marker-start", "marker-mid", "marker-end", "markerWidth", "markerHeight",
    "markerUnits", "orient", "refX", "refY", "patternUnits", "patternContentUnits", "patternTransform", "gradientUnits",
    "gradientTransform", "offset", "stop-color", "stop-opacity", "href", "role", "aria-label", "aria-labelledby",
    "aria-hidden", "color", "display", "visibility", "overflow", "vector-effect", "paint-order", "focusable",
    "pointer-events", "shape-rendering")
  style_properties <- c("fill", "fill-opacity", "fill-rule", "clip-rule", "stroke", "stroke-width", "stroke-opacity",
    "stroke-dasharray", "stroke-dashoffset", "stroke-linecap", "stroke-linejoin", "stroke-miterlimit", "opacity",
    "font-family", "font-size", "font-style", "font-weight", "text-anchor", "dominant-baseline", "alignment-baseline",
    "letter-spacing", "word-spacing", "white-space", "clip-path", "mask", "marker-start", "marker-mid", "marker-end",
    "color", "display", "visibility", "overflow", "vector-effect", "paint-order", "background", "background-color",
    "shape-rendering", "text-rendering", "image-rendering", "pointer-events")
  if (length(elements) > 50000L || any(!xml2::xml_name(elements) %in% allowed_elements)) team_canvas_fail("Unsafe saved SVG figure.")
  for (element in elements) {
    namespaces <- as.character(xml2::xml_ns(element))
    if (any(!namespaces %in% c("http://www.w3.org/2000/svg", "http://www.w3.org/1999/xlink", "http://www.w3.org/XML/1998/namespace")))
      team_canvas_fail("Unsafe saved SVG namespace.")
    attributes <- xml2::xml_attrs(element)
    attribute_names <- names(attributes)
    namespace_attributes <- attribute_names == "xmlns" | startsWith(attribute_names, "xmlns:")
    if (any(grepl("^on", attribute_names, ignore.case = TRUE)) ||
        any(!namespace_attributes & !attribute_names %in% allowed_attributes & !grepl("^data-[A-Za-z][A-Za-z0-9_-]*$", attribute_names)))
      team_canvas_fail("Unsafe saved SVG attributes.")
    for (index in seq_along(attributes)) {
      name <- attribute_names[[index]]; value <- attributes[[index]]
      if (namespace_attributes[[index]]) {
        if (!value %in% c("http://www.w3.org/2000/svg", "http://www.w3.org/1999/xlink", "http://www.w3.org/XML/1998/namespace"))
          team_canvas_fail("Unsafe saved SVG namespace.")
        next
      }
      if (!startsWith(name, "data-") && (grepl("\\", value, fixed = TRUE) || grepl("/*", value, fixed = TRUE)))
        team_canvas_fail("Unsafe saved SVG attribute encoding.")
      if (name == "href") {
        if (grepl("^#[A-Za-z0-9_.:-]+$", value)) next
        if (xml2::xml_name(element) == "image" && startsWith(value, "data:image/png;base64,")) {
          team_canvas_png(team_canvas_base64(substring(value, 23L, nchar(value)))); next
        }
        team_canvas_fail("External references are not allowed in saved SVG figures.")
      }
      if (name == "style") {
        if (grepl("[\\\\@<>]|/\\*|expression\\s*\\(", value, ignore.case = TRUE, perl = TRUE)) team_canvas_fail("Unsafe saved SVG style.")
        declarations <- trimws(strsplit(value, ";", fixed = TRUE)[[1]])
        declarations <- declarations[nzchar(declarations)]
        properties <- tolower(trimws(sub(":.*$", "", declarations)))
        if (any(!grepl(":", declarations, fixed = TRUE)) || any(!properties %in% style_properties)) team_canvas_fail("Unsafe saved SVG style.")
        calls <- regmatches(value, gregexpr("[A-Za-z-]+\\s*\\(", value, perl = TRUE))[[1]]
        if (length(calls) && any(!tolower(trimws(sub("\\($", "", calls))) %in% c("rgb", "rgba", "hsl", "hsla", "url")))
          team_canvas_fail("Unsafe saved SVG style function.")
      }
      # Paint references may point only to a local definition in this same SVG.
      if (grepl("url\\s*\\(", value, ignore.case = TRUE, perl = TRUE)) {
        without_local <- gsub("url\\(\\s*['\"]?#[A-Za-z0-9_.:-]+['\"]?\\s*\\)", "", value, ignore.case = TRUE, perl = TRUE)
        if (grepl("url\\s*\\(", without_local, ignore.case = TRUE, perl = TRUE)) team_canvas_fail("External references are not allowed in saved SVG figures.")
      }
      if (grepl("javascript\\s*:|vbscript\\s*:|https?\\s*:|file\\s*:", value, ignore.case = TRUE, perl = TRUE))
        team_canvas_fail("External references are not allowed in saved SVG figures.")
    }
  }
  invisible(TRUE)
}

team_canvas_image <- function(url) {
  url <- team_canvas_string(url, team_canvas_limits$snapshot, empty = FALSE)
  if (nchar(url, type = "bytes") > team_canvas_limits$snapshot) team_canvas_fail("A saved figure exceeds 4 MiB.")
  if (startsWith(url, "data:image/png;base64,")) {
    team_canvas_png(team_canvas_base64(substring(url, 23L, nchar(url))))
  } else {
    prefix <- "^data:image/svg\\+xml(;charset=utf-8)?(;base64)?,"
    if (!grepl(prefix, url, ignore.case = TRUE, perl = TRUE)) team_canvas_fail("Unsupported saved figure format.")
    header <- regmatches(url, regexpr(prefix, url, ignore.case = TRUE, perl = TRUE))
    # substring() defaults to last = 1,000,000 and silently truncates large snapshots.
    payload <- substring(url, nchar(header) + 1L, nchar(url))
    svg <- if (grepl(";base64,", header, fixed = TRUE)) {
      tryCatch(rawToChar(team_canvas_base64(payload)), error = function(e) team_canvas_fail("Invalid saved SVG encoding."))
    } else {
      if (grepl("%(?![0-9A-Fa-f]{2})|%00", payload, perl = TRUE)) team_canvas_fail("Invalid saved SVG encoding.")
      # utils::URLdecode repeatedly grows a raw vector and can monopolize
      # the Shiny event loop for minutes on a large Plotly SVG. curl performs
      # the same percent decoding in native code; keep the strict percent,
      # size, XML and reference validation around it unchanged.
      curl::curl_unescape(payload)
    }
    team_canvas_svg(svg)
  }
  url
}

# A cache is created inside each Team canvas server instance, so validated
# snapshots never cross session boundaries. Only successful validations are
# inserted. The URL remains the authoritative value: the SHA-256 digest is an
# index only, and a hit also requires byte-for-byte string equality.
team_canvas_image_cache <- function(max_bytes = team_canvas_limits$bytes, max_entries = 256L,
                                    hash = function(url) digest::digest(url, algo = "sha256", serialize = FALSE)) {
  if (!is.numeric(max_bytes) || length(max_bytes) != 1L || !is.finite(max_bytes) || max_bytes < 0)
    stop("Invalid Team canvas image cache bound.", call. = FALSE)
  if (!is.numeric(max_entries) || length(max_entries) != 1L || !is.finite(max_entries) ||
      max_entries < 0 || max_entries != floor(max_entries))
    stop("Invalid Team canvas image cache entry bound.", call. = FALSE)
  cache <- new.env(parent = emptyenv())
  cache$entries <- new.env(parent = emptyenv())
  cache$order <- character()
  cache$bytes <- 0
  cache$max_bytes <- as.numeric(max_bytes)
  cache$max_entries <- as.integer(max_entries)
  cache$hash <- hash
  cache
}

team_canvas_image_cache_clear <- function(cache) {
  rm(list = ls(envir = cache$entries, all.names = TRUE), envir = cache$entries)
  cache$order <- character()
  cache$bytes <- 0
  invisible(NULL)
}

team_canvas_image_cache_on_session_end <- function(session, cache) {
  session$onSessionEnded(function() team_canvas_image_cache_clear(cache))
  invisible(NULL)
}

team_canvas_image_cached <- function(url, cache, validate = team_canvas_image) {
  # Repeat the cheap shape and size checks even on a cache hit. Any content
  # edit changes the hash; collision candidates must also match exactly.
  url <- team_canvas_string(url, team_canvas_limits$snapshot, empty = FALSE)
  if (nchar(url, type = "bytes") > team_canvas_limits$snapshot) team_canvas_fail("A saved figure exceeds 4 MiB.")
  key <- cache$hash(url)
  if (!is.character(key) || length(key) != 1L || is.na(key) || !nzchar(key))
    team_canvas_fail("Unable to index a saved figure.")
  if (exists(key, envir = cache$entries, inherits = FALSE)) {
    entry <- get(key, envir = cache$entries, inherits = FALSE)
    if (identical(entry$url, url)) {
      cache$order <- c(cache$order[cache$order != key], key)
      return(url)
    }
  }

  # Do not populate the cache until the full format/XML/reference validation
  # succeeds. On a digest collision, validate normally but preserve the prior
  # entry rather than replacing it with ambiguous content.
  validated <- validate(url)
  if (cache$max_entries > 0L && !exists(key, envir = cache$entries, inherits = FALSE) &&
      nchar(url, type = "bytes") <= cache$max_bytes) {
    bytes <- nchar(url, type = "bytes")
    while (length(cache$order) &&
        (cache$bytes + bytes > cache$max_bytes || length(cache$order) >= cache$max_entries)) {
      evict <- cache$order[[1L]]
      cache$order <- cache$order[-1L]
      old <- get(evict, envir = cache$entries, inherits = FALSE)
      cache$bytes <- cache$bytes - old$bytes
      rm(list = evict, envir = cache$entries)
    }
    assign(key, list(url = url, bytes = bytes), envir = cache$entries)
    cache$order <- c(cache$order, key)
    cache$bytes <- cache$bytes + bytes
  }
  validated
}

# Editor fields are cosmetic allowlists: never accept data, scales or active references.
team_canvas_editor_text <- function(x, limit=500L) {
  x <- team_canvas_string(x, limit)
  x
}
team_canvas_hex <- function(x) {
  x <- team_canvas_string(x,7L,FALSE)
  if(!grepl("^#[0-9a-fA-F]{6}$",x)) team_canvas_fail()
  x
}
team_canvas_array <- function(x,limit) {
  if(!is.list(x)||!is.null(names(x))||length(x)>limit) team_canvas_fail()
  x
}
team_canvas_editor <- function(editor) {
  editor <- team_canvas_object(editor,c("layout","traces","annotations","categoryLabels","swapAxes","palette","greyHealthy"))
  if(!is.null(editor$swapAxes)) editor$swapAxes <- team_canvas_boolean(editor$swapAxes)
  if(!is.null(editor$greyHealthy)) editor$greyHealthy <- team_canvas_boolean(editor$greyHealthy)
  if(!is.null(editor$palette)) {
    editor$palette <- team_canvas_editor_text(editor$palette)
    if(!editor$palette %in% c("Gelato Days","Lab","Okabe–Ito","Nature (NPG)","Viridis"))team_canvas_fail()
  }
  texts <- c("title.text","xaxis.title.text","yaxis.title.text")
  colors <- c("paper_bgcolor","plot_bgcolor","font.color","title.font.color","legend.font.color","legend.bgcolor","xaxis.color","yaxis.color","xaxis.gridcolor","yaxis.gridcolor","xaxis.zerolinecolor","yaxis.zerolinecolor")
  sizes <- c("font.size","title.font.size","legend.font.size","xaxis.title.font.size","yaxis.title.font.size","xaxis.tickfont.size","yaxis.tickfont.size")
  positions <- c("title.x","title.y","legend.x","legend.y")
  bools <- c("showlegend",unlist(lapply(c("xaxis","yaxis"),function(a)paste0(a,".",c("showgrid","zeroline","showline","showticklabels")))))
  widths <- unlist(lapply(c("xaxis","yaxis"),function(a)paste0(a,".",c("gridwidth","zerolinewidth","linewidth"))))
  angles <- c("xaxis.tickangle","yaxis.tickangle")
  choices <- list("legend.orientation"=c("h","v"),"title.xanchor"=c("left","center","right","auto"),"legend.xanchor"=c("left","center","right","auto"),"title.yanchor"=c("top","middle","bottom","auto"),"legend.yanchor"=c("top","middle","bottom","auto"))
  for (family_key in c("font.family","title.font.family","legend.font.family")) choices[[family_key]] <- c("Arial","Helvetica","Verdana","Georgia","Times New Roman","Courier New","system-ui","sans-serif")
  if(!is.null(editor$layout)) {
    editor$layout <- team_canvas_object(editor$layout,c(texts,colors,sizes,positions,bools,widths,angles,names(choices)))
    for(k in names(editor$layout)) {
      v <- editor$layout[[k]]
      editor$layout[[k]] <- if(k %in% texts) team_canvas_editor_text(v) else if(k %in% colors) team_canvas_hex(v) else if(k %in% sizes) team_canvas_number(v,6,72) else if(k %in% positions) team_canvas_number(v,-2,3) else if(k %in% bools) team_canvas_boolean(v) else if(k %in% widths) team_canvas_number(v,0,10) else if(k %in% angles) team_canvas_number(v,-180,180) else {v<-team_canvas_editor_text(v);if(!v %in% choices[[k]])team_canvas_fail();v}
    }
  }
  indices <- numeric()
  if(!is.null(editor$traces)) editor$traces <- unname(lapply(team_canvas_array(editor$traces,100L),function(t) {
    t <- team_canvas_object(t,c("index","sourceKey","name","hidden","points","innerBox","color","fillColor","fillOpacity","lineColor","lineWidth","markerSize","opacity","scaleLow","scaleMid","scaleHigh"),"index")
    t$index <- team_canvas_number(t$index,0,999)
    if(t$index!=floor(t$index)||t$index %in% indices)team_canvas_fail()
    indices <<- c(indices,t$index)
    scale_fields <- c("scaleLow","scaleMid","scaleHigh");if(any(scale_fields %in% names(t)) && !all(scale_fields %in% names(t)))team_canvas_fail()
    for(k in setdiff(names(t),"index"))t[[k]] <- if(k %in% c("name","sourceKey"))team_canvas_editor_text(t[[k]]) else if(k %in% c("color","fillColor","lineColor",scale_fields))team_canvas_hex(t[[k]]) else if(k %in% c("hidden","points","innerBox"))team_canvas_boolean(t[[k]]) else team_canvas_number(t[[k]],0,if(k %in% c("opacity","fillOpacity"))1 else if(k=="lineWidth")20 else 100)
    if("hidden" %in% names(t) && (is.null(t$sourceKey) || !nzchar(t$sourceKey)))team_canvas_fail("Series visibility requires a source identity.")
    t
  }))
  if(!is.null(editor$annotations)) editor$annotations <- unname(lapply(team_canvas_array(editor$annotations,30L),function(a) {
    a <- team_canvas_object(a,c("text","x","y","xref","yref","showarrow","font"),c("text","x","y","xref","yref","showarrow","font"))
    a$text <- team_canvas_editor_text(a$text);a$x<-team_canvas_number(a$x,0,1);a$y<-team_canvas_number(a$y,0,1)
    if(!identical(a$xref,"paper")||!identical(a$yref,"paper")||!identical(a$showarrow,FALSE))team_canvas_fail()
    a$font <- team_canvas_object(a$font,c("size","color"),c("size","color"));a$font$size<-team_canvas_number(a$font$size,6,72);a$font$color<-team_canvas_hex(a$font$color)
    a
  }))
  if(!is.null(editor$categoryLabels)) {
    axes <- character()
    editor$categoryLabels <- unname(lapply(team_canvas_array(editor$categoryLabels,2L),function(a) {
      a <- team_canvas_object(a,c("axis","sourceKeys","values","labels"),c("axis","sourceKeys","values","labels"))
      a$axis <- team_canvas_string(a$axis,5L,FALSE)
      if(!a$axis %in% c("xaxis","yaxis") || a$axis %in% axes)team_canvas_fail()
      axes <<- c(axes,a$axis)
      a$sourceKeys <- unname(lapply(team_canvas_array(a$sourceKeys,100L),function(k)team_canvas_string(k,500L,FALSE)))
      if(!length(a$sourceKeys)||anyDuplicated(unlist(a$sourceKeys,use.names=FALSE)))team_canvas_fail()
      a$values <- unname(lapply(team_canvas_array(a$values,100L),team_canvas_editor_text))
      a$labels <- unname(lapply(team_canvas_array(a$labels,100L),team_canvas_editor_text))
      if(!length(a$values) || length(a$values)!=length(a$labels) || anyDuplicated(unlist(a$values,use.names=FALSE)))team_canvas_fail()
      a
    }))
  }
  editor
}
# Presentation choices for Group comparison, independent of model inputs.
team_canvas_group_comparison <- function(value) {
  if(nchar(team_canvas_json(value),type='bytes')>64*1024)team_canvas_fail('Group comparison presentation exceeds 64 KiB.')
  value<-team_canvas_object(value,c('features','hiddenConditions','panelOff','panelStyles'),c('features','hiddenConditions','panelOff','panelStyles'))
  if(any(vapply(value[c('features','hiddenConditions','panelOff','panelStyles')],is.null,logical(1))))team_canvas_fail()
  identifiers<-function(items,limit) {
    result<-unname(lapply(team_canvas_array(items,limit),function(x)team_canvas_string(x,500L,FALSE)))
    if(anyDuplicated(unlist(result,use.names=FALSE))||any(unlist(result,use.names=FALSE) %in% c('__proto__','prototype','constructor')))team_canvas_fail()
    result
  }
  dictionary<-function(items,limit) {
    if(!is.list(items)||length(items)>limit||(length(items)&&(is.null(names(items))||anyNA(names(items))||anyDuplicated(names(items)))))team_canvas_fail()
    for(key in names(items)) {team_canvas_string(key,500L,FALSE);if(key %in% c('__proto__','prototype','constructor'))team_canvas_fail()}
    if(!length(items))names(items)<-character()
    items
  }
  if(!is.null(value$features))value$features<-identifiers(value$features,500L)
  if(!is.null(value$hiddenConditions))value$hiddenConditions<-identifiers(value$hiddenConditions,100L)
  if(!is.null(value$panelOff)) {value$panelOff<-dictionary(value$panelOff,500L);for(k in names(value$panelOff))value$panelOff[[k]]<-identifiers(value$panelOff[[k]],100L)}
  if(!is.null(value$panelStyles)) {
    value$panelStyles<-dictionary(value$panelStyles,500L)
    for(k in names(value$panelStyles)) {
      style<-team_canvas_object(value$panelStyles[[k]],c('colors','points','box','lines'),c('colors','points','box'))
      if(any(vapply(style[c('colors','points','box')],is.null,logical(1))))team_canvas_fail()
      if(!is.null(style$points))style$points<-team_canvas_boolean(style$points)
      if(!is.null(style$box))style$box<-team_canvas_boolean(style$box)
      if(!is.null(style$colors)){style$colors<-dictionary(style$colors,100L);for(condition in names(style$colors))style$colors[[condition]]<-team_canvas_hex(style$colors[[condition]])}
      if(!is.null(style$lines)){style$lines<-dictionary(style$lines,100L);for(condition in names(style$lines))style$lines[[condition]]<-team_canvas_hex(style$lines[[condition]])}
      value$panelStyles[[k]]<-style
    }
  }
  value
}

team_canvas_document <- function(document,node_ids) {
  document<-team_canvas_object(document,c("version","layout","paper","orientation","items","paperWidth","paperHeight","showPageFurniture"),c("version","layout","paper","orientation","items"))
  if(!identical(document$version,"1")||!is.character(document$layout)||length(document$layout)!=1L||!document$layout %in% c("free","pages","arrangement","figure1")||!is.character(document$paper)||length(document$paper)!=1L||!document$paper %in% c("letter","a4","custom")||!is.character(document$orientation)||length(document$orientation)!=1L||!document$orientation %in% c("portrait","landscape"))team_canvas_fail()
  if(!is.null(document$showPageFurniture) && (!is.logical(document$showPageFurniture)||length(document$showPageFurniture)!=1L||is.na(document$showPageFurniture)))team_canvas_fail()
  if(document$paper=="custom") {
    document$paperWidth<-team_canvas_number(document$paperWidth,100,3000);document$paperHeight<-team_canvas_number(document$paperHeight,100,3000)
    size<-c(document$paperWidth,document$paperHeight)
  } else {
    if(!is.null(document$paperWidth)||!is.null(document$paperHeight))team_canvas_fail()
    size<-if(document$paper=="letter")c(612,792) else c(595.28,841.89)
    if(document$orientation=="landscape")size<-rev(size)
  }
  ids<-character()
  document$items<-unname(lapply(team_canvas_array(document$items,80L),function(item){
    item<-team_canvas_object(item,c("id","nodeId","type","x","y","width","height","caption","z","text","fontSize","color","shape","fill","stroke","strokeWidth","radius"),c("id","type","x","y","width","height","z"))
    item$id<-team_canvas_string(item$id,200,FALSE)
    if(!grepl("^[A-Za-z][A-Za-z0-9_-]{0,199}$",item$id)||item$id %in% ids||!is.character(item$type)||length(item$type)!=1L||!item$type %in% c("figure","text","shape"))team_canvas_fail()
    ids<<-c(ids,item$id)
    item$x<-team_canvas_number(item$x,0,size[1]);item$y<-team_canvas_number(item$y,0,size[2]);item$width<-team_canvas_number(item$width,20,size[1]);item$height<-team_canvas_number(item$height,20,size[2])
    if(item$x+item$width>size[1]+0.01||item$y+item$height>size[2]+0.01)team_canvas_fail()
    item$z<-team_canvas_number(item$z,0,10000);if(item$z!=floor(item$z))team_canvas_fail()
    if(item$type=="figure") {
      item<-team_canvas_object(item,c("id","nodeId","type","x","y","width","height","caption","z"),c("nodeId","caption"))
      item$nodeId<-team_canvas_string(item$nodeId,160,FALSE);if(!item$nodeId %in% node_ids)team_canvas_fail()
      item$caption<-team_canvas_editor_text(item$caption,1000L)
    } else if (item$type == "shape") {
      item<-team_canvas_object(item,c("id","type","x","y","width","height","shape","fill","stroke","strokeWidth","radius","z"),c("shape","fill","stroke","strokeWidth"))
      item$shape<-team_canvas_string(item$shape,16L,FALSE)
      if (!item$shape %in% c("rectangle","ellipse","line","arrow")) team_canvas_fail()
      for (key in c("fill","stroke")) {
        value<-team_canvas_string(item[[key]],9L,FALSE)
        if (!identical(value,"none") && (nchar(value) != 7L || !grepl("^#[0-9A-Fa-f]{6}$",value))) team_canvas_fail()
        item[[key]]<-tolower(value)
      }
      item$strokeWidth<-team_canvas_number(item$strokeWidth,0,20)
      if (!is.null(item$radius)) item$radius<-team_canvas_number(item$radius,0,100)
      if (item$shape %in% c("line","arrow") && !is.null(item$radius)) team_canvas_fail()
      item<-team_canvas_object(item,c("id","type","x","y","width","height","shape","fill","stroke","strokeWidth","radius","z"),c("shape","fill","stroke","strokeWidth"))
    } else {
      item<-team_canvas_object(item,c("id","type","x","y","width","height","text","fontSize","color","z"),c("text","fontSize","color"))
      item$text<-team_canvas_editor_text(item$text,2000L);item$fontSize<-team_canvas_number(item$fontSize,6,72);item$color<-team_canvas_hex(item$color)
    }
    item
  }))
  document
}

# Per-figure literature notes are presentation metadata, never analysis inputs.
team_canvas_insight <- function(value) {
  fields <- c("paragraph", "context_label", "searched_at", "fingerprint", "sources", "stale")
  value <- team_canvas_object(value, fields, fields)
  value$paragraph <- team_canvas_string(value$paragraph, 1800L, FALSE)
  if (grepl("[<>]", value$paragraph)) team_canvas_fail("Invalid insight text.")
  value$context_label <- team_canvas_string(value$context_label, 1000L, FALSE)
  value$searched_at <- team_canvas_string(value$searched_at, 80L, FALSE)
  value$fingerprint <- team_canvas_string(value$fingerprint, 64L, FALSE)
  if (!grepl("^[A-Fa-f0-9]{64}$", value$fingerprint)) team_canvas_fail("Invalid insight fingerprint.")
  value$stale <- team_canvas_boolean(value$stale)
  if (!is.list(value$sources) || !is.null(names(value$sources)) || length(value$sources) > 3L)
    team_canvas_fail("Invalid insight sources.")
  value$sources <- lapply(value$sources, function(source) {
    fields <- c("pmid", "title", "year", "url")
    source <- team_canvas_object(source, fields, fields)
    source$pmid <- team_canvas_string(source$pmid, 10L, FALSE)
    if (!grepl("^[1-9][0-9]*$", source$pmid)) team_canvas_fail("Invalid PubMed identifier.")
    source$title <- team_canvas_string(source$title, 500L, FALSE)
    if (grepl("[<>]", source$title)) team_canvas_fail("Invalid source title.")
    source$year <- team_canvas_string(source$year, 4L)
    if (!grepl("^([0-9]{4})?$", source$year)) team_canvas_fail("Invalid source year.")
    source$url <- team_canvas_string(source$url, 100L, FALSE)
    if (!identical(source$url, paste0("https://pubmed.ncbi.nlm.nih.gov/", source$pmid, "/")))
      team_canvas_fail("Invalid PubMed source URL.")
    source
  })
  value
}

# Per-copy violin statistics: confirmed settings, server-computed result and
# presentation. Restored results are re-verified against current data before
# they are drawn; this validator only bounds their shape. Mirrors
# www/team/js/canvas_statistics.js sanitize().
team_canvas_statistics <- function(value) {
  fail <- function() team_canvas_fail("Invalid saved violin statistics.")
  choice <- function(x, choices) { if (!is.character(x) || length(x) != 1L || is.na(x) || !x %in% choices) fail(); x }
  int <- function(x, low, high) { if (!is.numeric(x) || length(x) != 1L || !is.finite(x) || x != round(x) || x < low || x > high) fail(); as.integer(x) }
  num <- function(x, low, high, nullable = FALSE) { if (is.null(x) && nullable) return(NULL); team_canvas_number(x, low, high) }
  text <- function(x, max_chars, empty = FALSE) team_canvas_string(x, max_chars, empty)
  pairs <- function(x, low, high) {
    if (!is.list(x) || !is.null(names(x)) || length(x) < low || length(x) > high) fail()
    out <- lapply(x, function(pair) {
      if (!is.list(pair) && !is.character(pair)) fail()
      pair <- unlist(pair, use.names = FALSE)
      if (!is.character(pair) || length(pair) != 2L) fail()
      pair <- vapply(pair, text, character(1), max_chars = 500L, USE.NAMES = FALSE)
      if (identical(pair[[1L]], pair[[2L]])) fail()
      pair
    })
    if (anyDuplicated(vapply(out, function(pair) paste(sort(pair), collapse = "\r"), character(1)))) fail()
    out
  }
  value <- team_canvas_object(value, c("version", "presentation", "applied", "result"), c("version", "presentation"))
  if (!identical(value$version, "1")) team_canvas_fail("Unsupported saved violin statistics version.")
  applied <- NULL
  if (!is.null(value$applied)) {
    applied <- team_canvas_object(value$applied, c("test", "correction", "scope", "comparisons", "effect"), c("test", "correction", "scope", "comparisons", "effect"))
    applied$test <- choice(applied$test, c("welch", "wilcoxon"))
    applied$correction <- choice(applied$correction, c("holm", "BH", "bonferroni", "none"))
    applied$scope <- choice(applied$scope, c("displayed", "all_in_scope"))
    applied$effect <- choice(applied$effect, c("none", if (identical(applied$test, "welch")) "hedges_g" else "cliffs_delta"))
    applied$comparisons <- pairs(applied$comparisons, 1L, 45L)
  }
  declared <- if (is.null(applied)) character() else vapply(applied$comparisons, paste, character(1), collapse = "\r")
  p <- team_canvas_object(value$presentation, c("show", "pValue", "label", "fontSize", "spacing", "tip", "nDisplay", "hidden"),
    c("show", "pValue", "label", "fontSize", "spacing", "tip", "nDisplay", "hidden"))
  p$show <- team_canvas_boolean(p$show)
  p$pValue <- choice(p$pValue, c("adjusted", "raw")); p$label <- choice(p$label, c("exact", "stars", "both"))
  p$fontSize <- int(p$fontSize, 8, 28); p$spacing <- num(p$spacing, 0.03, 0.3); p$tip <- num(p$tip, 0, 0.1)
  p$nDisplay <- choice(p$nDisplay, c("samples", "participants", "both", "hidden"))
  p$hidden <- pairs(p$hidden, 0L, 45L)
  if (!all(vapply(p$hidden, paste, character(1), collapse = "\r") %in% declared)) fail()
  result <- NULL
  if (!is.null(value$result)) {
    if (is.null(applied)) fail()
    keys <- c("fingerprint", "dataFingerprint", "computedAt", "lipid", "grouping", "family", "groups", "rows", "provenance")
    result <- team_canvas_object(value$result, keys, keys)
    for (key in c("fingerprint", "dataFingerprint")) if (!grepl("^[a-f0-9]{64}$", text(result[[key]], 64L))) fail()
    result$computedAt <- text(result$computedAt, 64L)
    if (!grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,9})?Z$", result$computedAt)) fail()
    result$lipid <- text(result$lipid, 1000L); result$grouping <- choice(result$grouping, c("Group1", "Group2"))
    family <- team_canvas_object(result$family, c("m", "features", "comparisons", "untestable"), c("m", "features", "comparisons", "untestable"))
    family$features <- int(family$features, 1, 5000); family$comparisons <- int(family$comparisons, 1, 45)
    family$m <- int(family$m, 1, 20000); family$untestable <- int(family$untestable, 0, family$m)
    if (family$m != family$features * family$comparisons || family$comparisons != length(applied$comparisons) ||
        (identical(applied$scope, "displayed") && family$features != 1L)) fail()
    result$family <- family
    if (!is.list(result$groups) || !is.null(names(result$groups)) || length(result$groups) > 30L) fail()
    result$groups <- lapply(result$groups, function(g) {
      g <- team_canvas_object(g, c("group", "nSamples", "nExcluded", "nParticipants"), c("group", "nSamples", "nExcluded"))
      list(group = text(g$group, 500L), nSamples = int(g$nSamples, 0, 1e6), nExcluded = int(g$nExcluded, 0, 1e6),
           nParticipants = if (is.null(g$nParticipants)) NULL else int(g$nParticipants, 0, 1e6))
    })
    if (!is.list(result$rows) || !is.null(names(result$rows)) || length(result$rows) != length(applied$comparisons)) fail()
    result$rows <- lapply(seq_along(result$rows), function(i) {
      row <- team_canvas_object(result$rows[[i]], c("a", "b", "nA", "nB", "statistic", "df", "p", "pAdj", "effect", "note"), c("a", "b", "nA", "nB", "note"))
      if (!identical(c(text(row$a, 500L), text(row$b, 500L)), applied$comparisons[[i]])) fail()
      out <- list(a = row$a, b = row$b, nA = int(row$nA, 0, 1e6), nB = int(row$nB, 0, 1e6),
        statistic = num(row$statistic, -1e12, 1e12, TRUE), df = num(row$df, 0, 1e12, TRUE),
        p = num(row$p, 0, 1, TRUE), pAdj = num(row$pAdj, 0, 1, TRUE), effect = num(row$effect, -1e6, 1e6, TRUE),
        note = text(row$note, 300L, TRUE))
      if (is.null(out$p) != is.null(out$pAdj) || (!is.null(out$p) && out$pAdj < out$p - 1e-12)) fail()
      out
    })
    prov <- team_canvas_object(result$provenance, c("method", "transformation", "normalization", "imputation", "participantIds", "design"),
      c("method", "transformation", "normalization", "imputation", "participantIds", "design"))
    result$provenance <- list(method = text(prov$method, 2000L), transformation = text(prov$transformation, 500L),
      normalization = text(prov$normalization, 200L, TRUE), imputation = text(prov$imputation, 200L, TRUE),
      participantIds = choice(prov$participantIds, c("unique", "absent")), design = text(prov$design, 500L))
  }
  list(version = "1", presentation = p, applied = applied, result = result)
}

team_canvas_validate <- function(state, image_cache = NULL) {
  state <- team_canvas_object(state, c("version", "libraryHidden", "nodes", "document"), c("version", "libraryHidden", "nodes"))
  if (!identical(state$version, "1") && !identical(state$version, 1) && !identical(state$version, 1L)) team_canvas_fail("Unsupported figure canvas version.")
  hidden <- team_canvas_boolean(state$libraryHidden)
  if (!is.list(state$nodes) || !is.null(names(state$nodes)) || length(state$nodes) > team_canvas_limits$nodes) team_canvas_fail("A canvas supports at most 40 figures.")
  ids <- character()
  nodes <- lapply(state$nodes, function(node) {
    node <- team_canvas_object(node, c("kind", "assetVersion", "id", "label", "x", "y", "width", "height", "visual", "finished", "assetId", "color", "insight", "instance", "statistics"),
      c("id", "label", "x", "y", "width", "height", "visual"))
    id <- team_canvas_string(node$id, 160L, FALSE)
    if (!grepl("^[A-Za-z][A-Za-z0-9_-]{0,159}$", id) || id %in% ids) team_canvas_fail("Invalid or duplicate canvas plot identifier.")
    ids <<- c(ids, id)
    kind <- if (is.null(node$kind)) "plot" else team_canvas_string(node$kind, 16L, FALSE)
    if (!kind %in% c("plot", "illustration")) team_canvas_fail("Invalid canvas node kind.")
    if (identical(kind, "illustration") && !is.null(node$insight)) team_canvas_fail("Illustrations cannot have scientific insights.")
    insight <- if (is.null(node$insight)) NULL else team_canvas_insight(node$insight)
    asset_id <- NULL; illustration_color <- NULL
    if (identical(kind, "illustration")) {
      if (!identical(node$assetVersion, "1")) team_canvas_fail("Unsupported Team illustration asset version.")
      if (is.null(node$assetId) || !is.character(node$assetId) || length(node$assetId) != 1L ||
          !node$assetId %in% team_canvas_illustration_ids) team_canvas_fail("Unknown Team illustration asset.")
      if (is.null(node$color)) team_canvas_fail("Illustration color is required.")
      illustration_color <- team_canvas_string(node$color, 9L, FALSE)
      if (!grepl("^#[0-9A-Fa-f]{6}$", illustration_color)) team_canvas_fail("Invalid illustration color.")
      asset_id <- node$assetId
    }
    allowed_visual <- if (identical(kind, "illustration")) "background" else c("plotTitle", "xTitle", "yTitle", "fontSize", "fontColor", "markColor", "background", "editor", "groupComparison")
    visual <- team_canvas_object(node$visual, allowed_visual)
    for (key in names(visual)) {
      if (key == "editor") visual[[key]] <- team_canvas_editor(visual[[key]])
      else if (key == "groupComparison") visual[[key]] <- team_canvas_group_comparison(visual[[key]])
      else if (key == "fontSize") visual[[key]] <- team_canvas_number(visual[[key]], 8, 48)
      else if (key %in% c("fontColor", "markColor", "background")) {
        color <- team_canvas_string(visual[[key]], 9L, FALSE)
        if (!grepl("^#[0-9A-Fa-f]{6}([0-9A-Fa-f]{2})?$", color)) team_canvas_fail("Invalid canvas color.")
      } else visual[[key]] <- team_canvas_string(visual[[key]], 1000L)
    }
    finished <- node$finished
    if (!is.null(finished)) {
      finished <- team_canvas_object(finished, c("url", "createdAt", "stale", "provenance"), c("url", "createdAt", "stale"))
      finished$url <- if (is.null(image_cache)) team_canvas_image(finished$url) else
        team_canvas_image_cached(finished$url, image_cache)
      finished$createdAt <- team_canvas_string(finished$createdAt, 64L, FALSE)
      if (!grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,9})?Z$", finished$createdAt)) team_canvas_fail("Invalid saved figure date.")
      parsed_date <- strptime(finished$createdAt, "%Y-%m-%dT%H:%M:%OSZ", tz = "UTC")
      if (is.na(parsed_date) || format(parsed_date, "%Y-%m-%dT%H:%M:%S", tz = "UTC") != substring(finished$createdAt, 1L, 19L))
        team_canvas_fail("Invalid saved figure date.")
      finished$stale <- team_canvas_boolean(finished$stale)
      if (identical(kind, "illustration") && isTRUE(finished$stale)) team_canvas_fail("Illustration snapshots cannot be stale.")
      if (!is.null(finished$provenance)) {
        provenance <- finished$provenance
        if (!is.list(provenance) || length(provenance) > 16L || is.null(names(provenance)) ||
            anyDuplicated(names(provenance)) || any(!grepl("^[A-Za-z][A-Za-z0-9_]{0,63}$", names(provenance)))) team_canvas_fail("Invalid saved figure provenance.")
        for (value in provenance) {
          if (is.null(value)) next
          if (is.character(value)) team_canvas_string(value, 1000L)
          else if (is.logical(value)) team_canvas_boolean(value)
          else team_canvas_number(value, -1e15, 1e15)
        }
      }
    }
    if (identical(kind, "illustration")) visual$background <- "#ffffff"
    result_node <- list(kind = kind, assetVersion = if (identical(kind, "illustration")) "1" else NULL, id = id, label = team_canvas_string(node$label, 512L), x = team_canvas_number(node$x, 0, 1e6),
      y = team_canvas_number(node$y, 0, 1e6), width = team_canvas_number(node$width, 240, 4000),
      height = team_canvas_number(node$height, 220, 4000), visual = visual, finished = finished,
      assetId = asset_id, color = illustration_color)
    if (!is.null(insight)) result_node$insight <- insight
    if (!is.null(node$instance)) {
      if (!identical(kind,"plot")) team_canvas_fail("Only plots can have module instances.")
      result_node$instance <- team_plot_instance_validate(node$instance, id)
    }
    if (!is.null(visual$groupComparison) && (is.null(result_node$instance) || !identical(result_node$instance$source, 'group_comparison_tab-comparisonPlot'))) team_canvas_fail('Group comparison settings require their own independent instance.')
    if (!is.null(node$statistics)) {
      if (is.null(node$instance) || !identical(node$instance$source, "results_dashboard-plot_violin"))
        team_canvas_fail("Statistics are saved only for independent violin copies.")
      result_node$statistics <- team_canvas_statistics(node$statistics)
    }
    result_node
  })
  result <- list(version = "1", libraryHidden = hidden, nodes = unname(nodes))
  if (!is.null(state$document)) result$document <- team_canvas_document(state$document,ids)
  if (nchar(team_canvas_json(result), type = "bytes") > team_canvas_limits$bytes) team_canvas_fail("Figure canvas state exceeds 24 MiB.")
  result
}

team_canvas_json <- function(state) jsonlite::toJSON(state, auto_unbox = TRUE, null = "null", digits = NA)
team_canvas_read <- function(path) {
  if (!file.exists(path) || file.info(path)$size > team_canvas_limits$bytes) team_canvas_fail("Figure canvas state exceeds 24 MiB.")
  # Keep the figures validated while reading, indexed by content, so the import
  # that follows in the same restore does not validate the same SVGs again.
  cache <- team_canvas_image_cache()
  state <- team_canvas_validate(jsonlite::read_json(path, simplifyVector = FALSE), image_cache = cache)
  attr(state, "team_canvas_image_cache") <- cache
  state
}

# Copy figures already validated while reading an archive into a session cache.
# Entries are keyed by SHA-256 of the exact figure and re-checked for equality on
# every hit, so a changed figure is always validated again.
team_canvas_image_cache_adopt <- function(cache, from) {
  if (!is.environment(from) || !is.environment(from$entries)) return(invisible(cache))
  for (key in from$order) {
    entry <- get(key, envir = from$entries, inherits = FALSE)
    team_canvas_image_cached(entry$url, cache, validate = function(url) url)
  }
  invisible(cache)
}

team_canvas_server <- function(input, output, session, shared_data) {
  current <- shiny::reactiveVal(NULL)
  accepted_token <- shiny::reactiveVal(NULL)
  restore_token <- shiny::reactiveVal(NULL)
  restore_sequence <- 0L
  legacy_logratio_forced <- FALSE
  legacy_logratio_previous <- NULL
  legacy_logratio_outputs <- paste0("logratio_tab-", c("scrollable_plot_ui", "logratioPlot", "featureLevelUI", "featurePickerUI"))
  set_legacy_logratio_active <- function(state) {
    needed <- !is.null(state) && any(vapply(state$nodes, function(node)
      identical(node$id, 'logratio_tab-logratioPlot') && is.null(node$instance), logical(1)))
    if (needed && !legacy_logratio_forced) {
      previous <- lapply(legacy_logratio_outputs, function(id) shiny::outputOptions(output, id)$suspendWhenHidden)
      legacy_logratio_previous <<- previous
      for (id in legacy_logratio_outputs) shiny::outputOptions(output, id, suspendWhenHidden=FALSE)
      legacy_logratio_forced <<- TRUE
    } else if (!needed && legacy_logratio_forced) {
      for (i in seq_along(legacy_logratio_outputs)) {
        previous <- legacy_logratio_previous[[i]]
        shiny::outputOptions(output, legacy_logratio_outputs[[i]], suspendWhenHidden=if (is.null(previous)) TRUE else previous)
      }
      legacy_logratio_forced <<- FALSE
    }
  }
  image_cache <- team_canvas_image_cache()
  team_canvas_image_cache_on_session_end(session, image_cache)
  session$userData$team_canvas_acked_token <- function() shiny::isolate(accepted_token())
  session$userData$team_canvas_export <- function(provenance = NULL) {
    state <- shiny::isolate(current())
    if (is.null(state)) return(NULL)
    team_canvas_validate(state, image_cache = image_cache)
  }
  session$userData$team_canvas_import <- function(state = NULL, provenance = NULL) {
    if (!is.null(state)) {
      team_canvas_image_cache_adopt(image_cache, attr(state, "team_canvas_image_cache", exact = TRUE))
      attr(state, "team_canvas_image_cache") <- NULL
    }
    validated <- if (is.null(state)) NULL else team_canvas_validate(state, image_cache = image_cache)
    restore_sequence <<- restore_sequence + 1L
    token <- paste0('restore-', restore_sequence)
    restore_token(token); current(validated); accepted_token(NULL)
    session$sendCustomMessage('team-canvas-restore-status', list(status='pending', token=token))
    create <- session$userData$team_canvas_instances_create
    tryCatch({
      # Old checkpoints can contain the original logratio output rather than
      # an independent copy. Its renderUI parent is normally suspended while
      # Violin Plots is hidden, so mount that parent without navigating or
      # changing any scientific settings. Keep it active while the card exists.
      set_legacy_logratio_active(validated)
      if (is.function(create) && !is.null(validated)) for (node in validated$nodes) if (!is.null(node$instance)) create(node$instance)
    }, error=function(e) {
      session$sendCustomMessage('team-canvas-restore-status', list(status='failed', token=token))
      stop(e)
    })
    # Modules register synchronously; dispatch after that flush so the browser
    # can restore nodes against the newly registered scientific outputs.
    session$onFlushed(function() session$sendCustomMessage("team-canvas-restore", list(state = validated, restoreToken=token)), once = TRUE)
    invisible(validated)
  }
  shiny::observeEvent(input$team_canvas_restore_complete, {
    reply <- input$team_canvas_restore_complete
    expected <- shiny::isolate(restore_token())
    if (is.list(reply) && isTRUE(reply$ok) && is.character(reply$token) && length(reply$token)==1L && !is.null(expected) && identical(reply$token, expected)) restore_token(NULL)
  }, ignoreInit=TRUE, priority=200)
  shiny::observeEvent(input$team_canvas_restore_retry, {
    request <- input$team_canvas_restore_retry
    expected <- shiny::isolate(restore_token())
    if (!is.list(request) || !is.character(request$token) || length(request$token)!=1L || is.null(expected) || !identical(request$token, expected)) return()
    # Retry the validated server copy; never use the partially hydrated client.
    tryCatch(session$userData$team_canvas_import(shiny::isolate(current())), error=function(e) invisible(NULL))
  }, ignoreInit=TRUE, priority=200)
  shiny::observeEvent(input$team_canvas_state, {
    payload <- input$team_canvas_state
    # Keep a valid correlation token even when the envelope/state is rejected;
    # otherwise the browser cannot associate the negative acknowledgement.
    token <- tryCatch({
      value <- team_canvas_string(payload$token, 160L, FALSE)
      if (!grepl("^[A-Za-z0-9_.:-]+$", value)) team_canvas_fail("Invalid canvas checkpoint token.")
      value
    }, error = function(e) NULL)
    result <- tryCatch({
      payload <- team_canvas_object(payload, c("token", "state"), c("token", "state"))
      if (is.null(token)) team_canvas_fail("Invalid canvas checkpoint token.")
      if (!is.null(shiny::isolate(restore_token()))) team_canvas_fail("The saved figure workspace has not finished restoring.")
      team_canvas_validate(payload$state, image_cache = image_cache)
    }, error = identity)
    if (inherits(result, "error")) {
      accepted_token(NULL)
      session$sendCustomMessage("team-canvas-state-ack", list(token = token, ok = FALSE, message = conditionMessage(result)))
    } else {
      set_legacy_logratio_active(result)
      current(result); accepted_token(token)
      session$sendCustomMessage("team-canvas-state-ack", list(token = token, ok = TRUE, message = "Figure canvas saved for this checkpoint."))
    }
  # Authentication can register this handler after the first browser payload
  # already exists. Validate and acknowledge that payload as well as updates.
  }, ignoreInit = FALSE, priority = 100)
  invisible(NULL)
}
